        "SKILL_BUNDLE_INVALID",
        "ZIP local and central entries are inconsistent",
      );
    }
    entries.push({
      rawName,
      name,
      path,
      directory,
      compressedSize,
      originalSize,
      compression,
      localHeaderOffset,
    });
