function readU16(bytes: Uint8Array, offset: number): number {
  if (offset < 0 || offset + 2 > bytes.length) {
    fail("SKILL_BUNDLE_INVALID", "ZIP structure is truncated");
  }
  return (bytes[offset] ?? 0) | ((bytes[offset + 1] ?? 0) << 8);
