    files: validated.fileManifest,
  });
  canonicalFiles.set("skill.json", encoder.encode(`${stableJson(normalizedSkill)}\n`));

  const paths = [...canonicalFiles.keys()].sort(bytewisePathCompare);
  const zippable: Zippable = {};
  for (const path of paths) {
    const content = canonicalFiles.get(path);
    if (!content) continue;
    zippable[path] = [
      content,
      {
        attrs: REGULAR_FILE_MODE,
        level: 9,
        mtime: CANONICAL_MTIME,
        os: 3,
      },
    ];
  }
  const bytes = zipSync(zippable, {
    attrs: REGULAR_FILE_MODE,
    level: 9,
    mtime: CANONICAL_MTIME,
    os: 3,
  });
  if (bytes.byteLength > BUNDLE_LIMITS.compressedBytes) {
    throw new BundleValidationError(
      "SKILL_BUNDLE_TOO_LARGE",
      "Canonical bundle exceeds 10 MiB",
    );
  }
  const digestHex = await sha256Hex(bytes);
  const files: SkillFileManifestEntry[] = [];
  for (const path of paths) {
    const content = canonicalFiles.get(path);
    if (!content) continue;
    files.push({
      path,
      sha256: await sha256Hex(content),
      byteSize: content.byteLength,
      mediaType: mediaTypeForPath(path),
    });
  }
  const expandedByteSize = files.reduce((total, file) => total + file.byteSize, 0);
  const digest = `sha256:${digestHex}` as const;
  const manifest: BundleManifest = {
    formatVersion: 1,
    digest,
    byteSize: bytes.byteLength,
    expandedByteSize,
    fileCount: files.length,
    files,
  };
  return {
    bytes,
    digest,
    manifest,
    skill: normalizedSkill,
    files: canonicalFiles,
  };
}

/**
 * Builds and validates a canonical bundle from an already-extracted file set.
 * `skill.json` is always regenerated from the immutable skill identity and the
 * resulting inventory, so a caller cannot smuggle metadata changes through a
 * file amendment.
 */
export async function canonicalizeBundleFiles(options: {
  readonly skill: Omit<SkillJson, "files">;
  readonly files: ReadonlyMap<string, Uint8Array>;
}): Promise<CanonicalBundle> {
  const contentFiles = new Map<string, Uint8Array>();
  const collisionKeys = new Set<string>();
  for (const [rawPath, rawContent] of options.files) {
    const path = normalizeBundlePath(rawPath);
    if (path === "skill.json") continue;
    const collisionKey = bundlePathCollisionKey(path);
    if (collisionKeys.has(collisionKey)) {
      throw new BundleValidationError(
        "SKILL_PATH_DUPLICATE",
        "Bundle contains duplicate case-folded paths",
      );
    }
    collisionKeys.add(collisionKey);
    const content = new Uint8Array(rawContent.byteLength);
    content.set(rawContent);
    contentFiles.set(path, content);
  }
  const manifestFiles: SkillFileManifestEntry[] = [];
  for (const [path, content] of contentFiles) {
    manifestFiles.push({
      path,
      sha256: await sha256Hex(content),
      byteSize: content.byteLength,
      mediaType: mediaTypeForPath(path),
    });
  }
  manifestFiles.sort((left, right) => bytewisePathCompare(left.path, right.path));
  const skill = canonicalSkillJson({ ...options.skill, files: manifestFiles });
  const archiveFiles = new Map(contentFiles);
  archiveFiles.set("skill.json", encoder.encode(`${stableJson(skill)}\n`));
  const zippable: Zippable = {};
  for (const path of [...archiveFiles.keys()].sort(bytewisePathCompare)) {
    const content = archiveFiles.get(path);
    if (!content) continue;
    zippable[path] = [
      content,
      {
        attrs: REGULAR_FILE_MODE,
        level: 9,
        mtime: CANONICAL_MTIME,
        os: 3,
      },
    ];
  }
  return canonicalizeBundle(
    zipSync(zippable, {
      attrs: REGULAR_FILE_MODE,
      level: 9,
      mtime: CANONICAL_MTIME,
      os: 3,
    }),
  );
}
const encoder = new TextEncoder();

const ROOT_FILES = new Set(["SKILL.md", "skill.json"]);
const OPTIONAL_ROOTS = new Set(["assets", "references", "scripts"]);

export type BundlePathErrorCode =
  "SKILL_PATH_INVALID" | "SKILL_PATH_DUPLICATE" | "SKILL_LINK_INVALID";

export class BundlePathError extends Error {
  readonly code: BundlePathErrorCode;

  constructor(code: BundlePathErrorCode, message: string) {
    super(message);
    this.name = "BundlePathError";
    this.code = code;
  }
}

export function normalizeBundlePath(input: string, directory = false): string {
  if (!input || input.includes("\0") || input.includes("\\")) {
    throw new BundlePathError("SKILL_PATH_INVALID", "Bundle path is invalid");
  }
  const normalized = input.normalize("NFC");
  if (
    normalized.startsWith("/") ||
    /^[A-Za-z]:/.test(normalized) ||
    normalized.startsWith("//")
  ) {
    throw new BundlePathError("SKILL_PATH_INVALID", "Absolute paths are forbidden");
  }

  const withoutDirectorySuffix =
    directory && normalized.endsWith("/") ? normalized.slice(0, -1) : normalized;
  const segments = withoutDirectorySuffix.split("/");
  if (
    segments.length === 0 ||
    segments.some(
      (segment) =>
        segment.length === 0 || segment === "." || segment === ".." || segment === "~",
    )
  ) {
    throw new BundlePathError(
      "SKILL_PATH_INVALID",
      "Empty and traversing path segments are forbidden",
    );
  }
  if (encoder.encode(withoutDirectorySuffix).byteLength > 240) {
    throw new BundlePathError("SKILL_PATH_INVALID", "Bundle path is too long");
  }

  const [root] = segments;
  if (
    (!directory && segments.length === 1 && !ROOT_FILES.has(withoutDirectorySuffix)) ||
    (segments.length > 1 && !OPTIONAL_ROOTS.has(root ?? "")) ||
    (directory && !OPTIONAL_ROOTS.has(root ?? ""))
  ) {
    throw new BundlePathError(
      "SKILL_PATH_INVALID",
      "Bundle path uses an unsupported top-level entry",
    );
  }
  if (!directory && OPTIONAL_ROOTS.has(withoutDirectorySuffix)) {
    throw new BundlePathError(
      "SKILL_PATH_INVALID",
      "Optional bundle roots must be directories",
    );
  }
  return withoutDirectorySuffix;
}

export function bundlePathCollisionKey(path: string): string {
  return path.normalize("NFC").toLowerCase();
}

export function bytewisePathCompare(left: string, right: string): number {
  const a = encoder.encode(left);
  const b = encoder.encode(right);
  const length = Math.min(a.length, b.length);
  for (let index = 0; index < length; index += 1) {
    const difference = (a[index] ?? 0) - (b[index] ?? 0);
    if (difference !== 0) return difference;
  }
  return a.length - b.length;
}

export function assertStorageIdentifier(value: string, label: string): string {
  if (!/^[A-Za-z0-9:_-]{1,160}$/.test(value)) {
    throw new BundlePathError(
      "SKILL_PATH_INVALID",
      `${label} is not safe for an object key`,
    );
  }
  return value;
}
