import { type z } from "zod";
import { type SkillResolveInput, type verificationStartInputSchema, type verificationEvidenceInputSchema, type verificationCompleteInputSchema, type verificationRunInputSchema, type dependencyUpgradeInputSchema, McpToolError } from "@skillplane/mcp-schema";
import { registerResourceRoutes } from "@skillplane/api";
import { executeReadTool, executeMutationTool, type McpToolRuntime } from "./shared.js";
import { resolveSkill,resolveVersion } from "./resolve.js";
export function skillResolve(runtime:McpToolRuntime,input:SkillResolveInput) {
  return executeReadTool(runtime,input.purpose==="verify"?"skill_verification_plan_get":"skill_resolve",input.caller,async execution=>{
    const skill=await resolveSkill(runtime,execution,input.skill,{action:"skills:read",allowPublic:true});
    const version=await resolveVersion(runtime,execution,skill,input.version);
    return {output:{requestId:execution.requestId,plan:await runtime.services.compositionService.resolve(version.id,skill.principal,input.purpose)}};
  });
}
export function verificationStart(runtime:McpToolRuntime,input:z.infer<typeof verificationStartInputSchema>) {
  return executeMutationTool(runtime,"skill_verification_run_start",input.caller,async execution=>{
    const skill=await resolveSkill(runtime,execution,input.skill,{action:"skills:read",allowPublic:false});
    if(!skill.principal) throw new McpToolError("WORKSPACE_FORBIDDEN","Workspace access is required");
    const version=await resolveVersion(runtime,execution,skill,input.version);
    const result=await runtime.services.verificationService.start({...input,versionId:version.id,principal:skill.principal,requestId:execution.requestId,fencingEpoch:runtime.fencingEpoch});
    return {output:{requestId:execution.requestId,result}};
  });
}
export function verificationGet(runtime:McpToolRuntime,input:z.infer<typeof verificationRunInputSchema>) {
  return executeReadTool(runtime,"skill_verification_run_get",input.caller,async execution=>{
    const skill=await resolveSkill(runtime,execution,input.skill,{action:"skills:read",allowPublic:false});
    if(!skill.principal) throw new McpToolError("WORKSPACE_FORBIDDEN","Workspace access is required");
    const result=await runtime.services.verificationService.get(input.runId,skill.principal);
    const plan=await runtime.services.compositionService.resolve(result.version_id,skill.principal,"verify");
    if(plan.root.skillId!==skill.id) throw new McpToolError("NOT_FOUND","Verification run was not found");
    return {output:{requestId:execution.requestId,result}};
  });
}
export function verificationEvidence(runtime:McpToolRuntime,input:z.infer<typeof verificationEvidenceInputSchema>) {
  return executeMutationTool(runtime,"skill_verification_evidence_add",input.caller,async execution=>{
    const skill=await resolveSkill(runtime,execution,input.skill,{action:"skills:read",allowPublic:false});
    if(!skill.principal) throw new McpToolError("WORKSPACE_FORBIDDEN","Workspace access is required");
    const result=await runtime.services.verificationService.addEvidence({...input,principal:skill.principal,requestId:execution.requestId,fencingEpoch:runtime.fencingEpoch});
    return {output:{requestId:execution.requestId,result}};
  });
}
export function verificationComplete(runtime:McpToolRuntime,input:z.infer<typeof verificationCompleteInputSchema>) {
  return executeMutationTool(runtime,"skill_verification_run_complete",input.caller,async execution=>{
    const skill=await resolveSkill(runtime,execution,input.skill,{action:"skills:read",allowPublic:false});
    if(!skill.principal) throw new McpToolError("WORKSPACE_FORBIDDEN","Workspace access is required");
    const result=await runtime.services.verificationService.complete({...input,principal:skill.principal,requestId:execution.requestId,fencingEpoch:runtime.fencingEpoch});
    return {output:{requestId:execution.requestId,result}};
  });
}
export function dependencyUpgrade(runtime:McpToolRuntime,input:z.infer<typeof dependencyUpgradeInputSchema>) {
  return executeMutationTool(runtime,"skill_dependency_upgrade",input.caller,async execution=>{
    const skill=await resolveSkill(runtime,execution,input.skill,{action:"skills:write",allowPublic:false});
    if(!skill.principal) throw new McpToolError("WORKSPACE_FORBIDDEN","Workspace access is required");
    const version=await resolveVersion(runtime,execution,skill,input.version);
    const bundle=await runtime.services.bundleStorage.getCanonicalBundle(version.objectKey,version.digest);
    const candidate=await runtime.services.skillVersionService.createCandidate({skillId:skill.id,principal:skill.principal,baseVersionId:version.id,proposedBump:input.proposedBump,changeSummary:"Upgrade locked skill dependencies",archiveBytes:bundle.bytes,idempotencyKey:input.idempotencyKey,requestId:execution.requestId,fencingEpoch:runtime.fencingEpoch});
    await registerResourceRoutes(runtime.services,skill.workspaceId,[{resourceType:"skill_version",resourceId:candidate.id}]);
    const diff=await runtime.services.skillVersionService.diff({skillId:skill.id,fromVersionId:version.id,toVersionId:candidate.id,principal:skill.principal});
    return {output:{requestId:execution.requestId,result:{candidate,diff}}};
  });
}
