import { DomainError } from "@skillplane/domain";
import { verificationStartFieldsSchema,verificationResultSchema } from "@skillplane/mcp-schema";
import type { Hono } from "hono";
import type { ApiEnvironment } from "../context.js";
import { success } from "../envelopes.js";
import { registerResourceRoutes } from "../resource-routing.js";
import { readJsonObject,requireIdempotencyKey,requirePrincipal,routingEpoch } from "./shared.js";
export function registerCompositionRoutes(app:Hono<ApiEnvironment>) {
  app.get("/api/v1/skills/:skillId/versions/:versionId/resolve",async c=>{
    const services=c.get("services"); if(!services) throw new DomainError("NOT_FOUND","Skill was not found",404);
    const purpose=c.req.query("purpose") ?? "execute";
    if(purpose!=="execute" && purpose!=="verify") throw new DomainError("VALIDATION_FAILED","Invalid resolution purpose",400);
    const plan=await services.compositionService.resolve(c.req.param("versionId"),c.get("principal"),purpose,Boolean(c.get("principal")));
    if(plan.root.skillId!==c.req.param("skillId")) throw new DomainError("NOT_FOUND","Skill was not found",404);
    c.header("Cache-Control","private, no-store");return c.json(success(c,{plan}));
  });
  app.post("/api/v1/skills/:skillId/versions/:versionId/dependency-upgrade",async c=>{
    const s=c.get("services")!;const principal=requirePrincipal(c);
    const bundle=await s.skillVersionService.retrieveBundle({skillId:c.req.param("skillId"),versionId:c.req.param("versionId"),principal});
    const version=await s.skillVersionService.createCandidate({skillId:c.req.param("skillId"),baseVersionId:c.req.param("versionId"),principal,archiveBytes:bundle.bytes,proposedBump:"minor",changeSummary:"Upgrade locked skill dependencies",idempotencyKey:requireIdempotencyKey(c),requestId:c.get("requestId"),fencingEpoch:routingEpoch(c)});
    await registerResourceRoutes(s,principal.workspaceId,[{resourceType:"skill_version",resourceId:version.id}]);
    return c.json(success(c,{version}),201);
  });
  app.post("/api/v1/skills/:skillId/versions/:versionId/verification-runs",async c=>{
    const s=c.get("services")!;const principal=requirePrincipal(c);
    const fields=verificationStartFieldsSchema.safeParse(await readJsonObject(c));
    if(!fields.success) throw new DomainError("VALIDATION_FAILED","Invalid verification target",400);
    const plan=await s.compositionService.resolve(c.req.param("versionId"),principal,"verify");
    if(plan.root.skillId!==c.req.param("skillId")) throw new DomainError("NOT_FOUND","Skill was not found",404);
    const run=await s.verificationService.start({...fields.data,versionId:plan.root.versionId,principal,idempotencyKey:requireIdempotencyKey(c),requestId:c.get("requestId"),fencingEpoch:routingEpoch(c)});
    return c.json(success(c,{run}),201);
  });
  app.get("/api/v1/skills/:skillId/verification-runs/:runId",async c=>{
    const s=c.get("services")!;const principal=requirePrincipal(c);
    const run=await s.verificationService.get(c.req.param("runId"),principal);
    const plan=await s.compositionService.resolve(run.version_id,principal,"verify");
    if(plan.root.skillId!==c.req.param("skillId")) throw new DomainError("NOT_FOUND","Verification run was not found",404);
    c.header("Cache-Control","private, no-store");return c.json(success(c,{run}));
  });
  app.post("/api/v1/skills/:skillId/verification-runs/:runId/evidence",async c=>{
    const parsed=verificationResultSchema.safeParse(await readJsonObject(c));
    if(!parsed.success) throw new DomainError("VALIDATION_FAILED","Invalid claim evidence",400);
    const result=await c.get("services")!.verificationService.addEvidence({runId:c.req.param("runId"),result:parsed.data,principal:requirePrincipal(c),idempotencyKey:requireIdempotencyKey(c),requestId:c.get("requestId"),fencingEpoch:routingEpoch(c)});
    return c.json(success(c,result));
  });
  app.post("/api/v1/skills/:skillId/verification-runs/:runId/complete",async c=>{
    const run=await c.get("services")!.verificationService.complete({runId:c.req.param("runId"),principal:requirePrincipal(c),idempotencyKey:requireIdempotencyKey(c),requestId:c.get("requestId"),fencingEpoch:routingEpoch(c)});
    return c.json(success(c,{run}));
  });
}
