  it("rejects scaffold-only evidence and unaccounted surfaces",()=>{expect(evaluateVerification(claims,[{...pass,evidence:[evidence("package-installation")]}])).toBe("unknown");expect(evaluateVerification(claims,[])).toBe("unknown");});
