s=s.replace(needle,'''  app.get("/api/v1/skills/:skillId/versions/:versionId/dependency-upgrade",async c=>{
    const s=c.get("services")!;const principal=requirePrincipal(c);
    await s.skillVersionService.get({skillId:c.req.param("skillId"),versionId:c.req.param("versionId"),principal});
    return c.json(success(c,await s.compositionService.upgradePreview(c.req.param("versionId"),principal)));
  });
  app.post("/api/v1/skills/:skillId/versions/:versionId/lifecycle",async c=>{
    const fields=await readJsonObject(c);const state=fields.state;
    if(state!=="deprecated" && state!=="revoked")throw new DomainError("VALIDATION_FAILED","Invalid lifecycle state",400);
    const result=await c.get("services")!.versionLifecycleService.set({skillId:c.req.param("skillId"),versionId:c.req.param("versionId"),state,reason:parseStringField(fields.reason,"reason"),principal:requirePrincipal(c),idempotencyKey:requireIdempotencyKey(c),requestId:c.get("requestId"),fencingEpoch:routingEpoch(c)});
    return c.json(success(c,result));
  });
  app.get("/api/v1/skills/:skillId/versions/:versionId/dependents",async c=>{
    const s=c.get("services")!;const principal=requirePrincipal(c);
    await s.skillVersionService.get({skillId:c.req.param("skillId"),versionId:c.req.param("versionId"),principal});
