  const bucket:R2BucketLike={
    async head(key){const r=records.get(key);return r?{key,size:r.bytes.length,etag:key,customMetadata:r.metadata}:null;},
    async get(key){const r=records.get(key);return r?{key,size:r.bytes.length,etag:key,customMetadata:r.metadata,async arrayBuffer(){return r.bytes.slice().buffer;}}:null;},
    async put(key,bytes,options){if(records.has(key)&&options?.onlyIf?.etagDoesNotMatch==="*")return null;records.set(key,{bytes:bytes.slice(),metadata:options?.customMetadata??{}});return {key,size:bytes.length,etag:key};},
    async delete(keys){for(const k of typeof keys==="string"?[keys]:keys)records.delete(k);},
    async list(){return {objects:[],truncated:false};}
  };
  const storage=new R2BundleRepository(bucket),composition=new CompositionService(pool,storage);
  const skills=new SkillService(pool,storage,pool,composition),versions=new SkillVersionService(pool,storage,skills.idempotency,composition),publication=new PublicationService(pool,storage,skills.idempotency,composition),verification=new VerificationService(pool,composition,skills.idempotency),lifecycle=new VersionLifecycleService(pool,pool,skills.idempotency);
  let principal:Principal,foreign:Principal,workspaceSlug:string;
  const mutation=()=>({principal,idempotencyKey:crypto.randomUUID(),requestId:crypto.randomUUID()});
  const claim={id:"datafn.read-surfaces",statement:"Every read surface uses DataFn",severity:"blocking",scope:"All application reads and mutations",requiredEvidence:["surface-inventory","bypass-scan","runtime-traces"],prohibitedBypasses:["direct SQL"],rules:{pass:"Every surface traced through DataFn",fail:"A bypass exists",unknown:"Any unaccounted surface"}};
  const dependency=(slug:string):SkillDependency=>({alias:slug,workspace:workspaceSlug,skill:slug,version:"^1.0.0",scope:"execution",mode:"invoke",required:true});
