    const files=new Map([["SKILL.md",new TextEncoder().encode(text)]]);
    if(withClaims){files.set("verification/VERIFY.md",new TextEncoder().encode("Independently inventory, trace and test every surface."));files.set("verification/claims.json",new TextEncoder().encode(JSON.stringify([claim])));}
    if(spoof)files.set("skill.lock.json",new TextEncoder().encode('{"forged":true}'));
    return canonicalizeBundleFiles({skill:{formatVersion:2,name:slug,slug,description:"",tags:[],entrypoints:{execute:"SKILL.md",...(withClaims?{verify:"verification/VERIFY.md" as const}:{})},dependencies:deps,...(withClaims?{verification:{claims:"verification/claims.json" as const,blocking:true}}:{})},files});
  }
