import { describe, expect, it } from "vitest";
import { BundleValidationError, StorageError } from "@skillplane/storage";
import {
  mapPublicProjectionFileError,
  PublicSkillProjectionService,
} from "./public-projections.js";

const row = (id: string, score: string) => ({
  workspace_id: "workspace:one",
  workspace_slug: "one",
  skill_id: id,
  skill_slug: id.replace("skill:", ""),
  version_id: `version:${id}`,
  semantic_version: "1.0.0",
  digest: `sha256:${"a".repeat(64)}`,
  object_key: `public/${id}.zip`,
  document: {
    skill: { name: id, description: "description", tags: ["search"] },
    version: { revision: 1, publishedAt: "2026-08-01T00:00:00.000Z" },
  },
  published_at: new Date("2026-08-29T00:00:00.000Z"),
  score,
});

describe("global public projection search", () => {
  it("uses relevance keyset pagination and binds cursors to filters", async () => {
    const calls: { text: string; values: readonly unknown[] }[] = [];
    const pool = {
      async query(text: string, values: readonly unknown[]) {
        calls.push({ text, values });
        return calls.length === 1
          ? {
              rows: [
                row("skill:a", "900"),
                row("skill:b", "800"),
                row("skill:c", "700"),
              ],
            }
{
  "minimal": {
    "digest": "sha256:89a1ce5aedcab433c01bee721e93fd9a989a0bc4aa8ab4f54c4d4cb21bae376f",
    "byteSize": 465
  },
  "portable": {
    "digest": "sha256:c80839837c5bad80842caf1035ff26b82c9a0836c5416cf96ad797c64c24a972",
    "byteSize": 900
    if (bundle.skill.formatVersion === 1) return {bundle,lock:emptyLock(),closureDigest:await compositionDigest(bundle.digest,emptyLock())};
    authorize(principal,"skills:read");
    const files = new Map(bundle.files); files.delete("skill.lock.json");
    const authored = await canonicalizeBundleFiles({skill:bundle.skill,files});
    const root = {workspace:await this.workspaceSlug(principal.workspaceId),skill:bundle.skill.slug,expandedBytes:authored.manifest.expandedByteSize};
    const lock = preserveLock ? this.lock(bundle) : await resolveDependencies({dependencies:bundle.skill.dependencies,root,choices:d=>this.choices(d,principal)});
    validateLock(lock,root);
    await this.revalidate(lock,principal,visibility);
    files.set("skill.lock.json",new TextEncoder().encode(`${stableJson(lock)}\n`));
    const canonical = await canonicalizeBundleFiles({skill:bundle.skill,files});
    validateLock(lock,{...root,expandedBytes:canonical.manifest.expandedByteSize});
    return {bundle:canonical,lock,closureDigest:await compositionDigest(canonical.digest,lock)};
  }
  async revalidate(lock: DependencyLock, principal: Principal | null, visibility: string, db: Queryable = this.pool): Promise<void> {
    for (const locked of lock.nodes) {
      const source = await this.source(locked.versionId,principal,db);
      if (source.status !== "published") this.denied();
      if ((visibility === "public" || source.workspace_id !== principal?.workspaceId) && source.visibility !== "public") this.denied();
      if (visibility === "workspace" && source.visibility === "private") this.denied();
      if (stableJson(await this.node(source)) !== stableJson(locked)) throw new DomainError("SKILL_DEPENDENCY_CONFLICT","Locked dependency identity changed",409);
    }
  }
  async persist(client: PoolClient, versionId: string, workspaceId: string, prepared: PreparedComposition): Promise<void> {
    if (prepared.bundle.skill.formatVersion === 1) return;
    for (const edge of prepared.lock.edges) {
      const child = prepared.lock.nodes.find(n=>n.versionId===edge.child)!;
      await client.query(`INSERT INTO skill_version_dependencies (workspace_id, root_version_id, parent_version_id, alias, ordinal, child_version_id, edge, node)
        VALUES ($1,$2,$3,$4,$5,$6,$7,$8)`,[workspaceId,versionId,edge.parent==="$root"?versionId:edge.parent,edge.alias,edge.ordinal,edge.child,edge,child]);
    }
    await client.query(`INSERT INTO skill_version_compositions (workspace_id,version_id,format_version,dependency_closure_digest,dependency_lock)
      VALUES ($1,$2,2,$3,$4)`,[workspaceId,versionId,prepared.closureDigest,prepared.lock]);
  }
  async validatePublication(versionId: string, principal: Principal, visibility: string, db: Queryable): Promise<void> {
    const result = await db.query<{format_version:number;dependency_lock:DependencyLock|null;dependency_closure_digest:string|null}>("SELECT (v.manifest->>'formatVersion')::integer AS format_version,c.dependency_lock,c.dependency_closure_digest FROM skill_versions v LEFT JOIN skill_version_compositions c ON c.version_id=v.id AND c.workspace_id=v.workspace_id WHERE v.id=$1 AND v.workspace_id=$2",[versionId,principal.workspaceId]);
    const row=result.rows[0];
    if(row?.format_version===2) {
      if(!row.dependency_lock || !row.dependency_closure_digest)throw new DomainError("SKILL_DEPENDENCY_CONFLICT","Candidate has no immutable normalized lock",409);
      const source=await this.source(versionId,principal,db);
      if(stableJson(row.dependency_lock)!==stableJson(this.lock(source.bundle)) || row.dependency_closure_digest!==(await this.node(source)).closureDigest)throw new DomainError("SKILL_DEPENDENCY_CONFLICT","Candidate lock disagrees with its canonical bundle",409);
      await this.revalidate(row.dependency_lock,principal,visibility,db);
    }
  }

  async resolve(versionId: string, principal: Principal | null, purpose: "execute" | "verify" = "execute", allowCandidate = false): Promise<CompositionPlan> {
    if (principal) authorize(principal,"skills:read");
    const source = await this.source(versionId,principal);
    if (source.status !== "published" && !(allowCandidate && principal && principal.role!=="viewer" && source.workspace_id === principal.workspaceId && (principal.kind==="user" || principal.scopes.includes("skills:amend")))) this.denied();
    const root = await this.node(source);
    const lock = this.lock(source.bundle);
    await this.revalidate(lock,principal,source.visibility);
    const sources = new Map<string,Source>([[versionId,source]]);
    for (const n of lock.nodes) sources.set(n.versionId,await this.source(n.versionId,principal));
    const executionIds = new Set<string>(); const verificationIds = new Set<string>();
    const visit = (id: string, execution: boolean) => {
      const parent = id === versionId ? "$root" : id;
      if (execution && executionIds.has(id)) return;
      if (!execution && verificationIds.has(id)) return;
      verificationIds.add(id);
      for (const edge of lock.edges.filter(e=>e.parent===parent)) visit(edge.child,execution && edge.scope!=="verification");
      if (execution) executionIds.add(id);
    };
    visit(versionId,true);
    const module = (id:string, verify:boolean): ResolvedModule | null => {
      const s=sources.get(id)!; const skill=s.bundle.skill;
      const path=verify ? (skill.formatVersion===2?skill.entrypoints.verify:undefined) : "SKILL.md";
      if (!path) return null;
      return {versionId:id,workspace:s.workspace_slug,skill:s.skill_slug,digest:s.content_digest,instructions:new TextDecoder().decode(s.bundle.files.get(path)),files:s.bundle.manifest.files};
    };
    const claims: CompositionPlan["verificationPlan"]["claims"]=[];
    for (const id of verificationIds) {
      const s=sources.get(id)!;
      if(s.bundle.skill.formatVersion===2 && s.bundle.skill.verification) {
        const parsed=verificationClaimsSchema.parse(JSON.parse(new TextDecoder().decode(s.bundle.files.get(s.bundle.skill.verification.claims))));
        for (const claim of parsed) claims.push({...claim,namespacedId:`${id}/${claim.id}`,originatingVersionId:id});
      }
    }
    claims.sort((a,b)=>a.namespacedId<b.namespacedId?-1:a.namespacedId>b.namespacedId?1:0);
    return {root,closureDigest:root.closureDigest,dag:lock,executionPlan:{modules:purpose==="verify"?[]:[...executionIds].map(id=>module(id,false)).filter((m):m is ResolvedModule=>m!==null),invocations:purpose==="verify"?[]:lock.edges.filter(e=>e.mode==="invoke" && e.scope!=="verification")},verificationPlan:{modules:[...verificationIds].map(id=>module(id,true)).filter((m):m is ResolvedModule=>m!==null),claims},warnings:[...sources.values()].filter(s=>s.deprecated_at).map(s=>`Deprecated version: ${s.id}`)};
  }
}
